        addLabelKey: 'HOME.PLAYLISTS.SOURCE_XTREAM_ADD',
        contentKeys: [
            'HOME.PLAYLISTS.CONTENT_LIVE',
            'HOME.PLAYLISTS.CONTENT_VOD',
            'HOME.PLAYLISTS.CONTENT_SERIES',
            'HOME.PLAYLISTS.CONTENT_EPG',
