@Component({
    selector: 'app-empty-state',
    templateUrl: './empty-state.component.html',
    styleUrls: [
        './empty-state.component.scss',
        './empty-state.responsive.scss',
        './empty-state.themes.scss',
    ],
    imports: [MatButtonModule, MatIcon, TranslatePipe],
})
export class EmptyStateComponent {
    readonly type = input.required<EmptyStateType>();

    readonly icon = input<string>('inbox');
    readonly titleKey = input<string>('');
    readonly descriptionKey = input<string>('');
    readonly primaryActionLabelKey = input<string | null>(null);
    readonly secondaryActionLabelKey = input<string | null>(null);

    readonly showElectronOnlyValueProps = input<boolean>(false);

    readonly addPlaylistClicked = output<WorkspacePlaylistType | undefined>();
    readonly primaryActionClicked = output<void>();
    readonly secondaryActionClicked = output<void>();

    readonly featureCards = FEATURE_CARDS;
    readonly sourceCards = SOURCE_CARDS;

    onAddPlaylist(type?: WorkspacePlaylistType): void {
        this.addPlaylistClicked.emit(type);
    }

    onPrimaryAction(): void {
        this.primaryActionClicked.emit();
    }

    onSecondaryAction(): void {
        this.secondaryActionClicked.emit();
    }

    isFeatureCardVisible(card: FeatureCard): boolean {
        return !card.electronOnly || this.showElectronOnlyValueProps();
    }
}

@if (playlistsData(); as data) {
    @if (data.playlists.length === 0) {
        @if (data.totalCount === 0) {
            <!-- Welcome state: no playlists at all -->
            <app-empty-state
                [type]="'welcome'"
                [showElectronOnlyValueProps]="isElectron"
                (addPlaylistClicked)="onAddPlaylist($event)"
            />
        } @else {
            <!-- No results state: search/filter returned nothing -->
            <app-empty-state [type]="'no-results'" />
        }
    } @else {
        <div
            class="playlists-list"
            cdkDropList
            [cdkDropListDisabled]="!isCustomSortActive()"
            (cdkDropListDropped)="drop($event, data.playlists)"
        >
            @for (
                item of data.playlists;
                track item._id;
                let last = $last
            ) {
                <app-playlist-item
                    [item]="item"
                    [isSelected]="activePlaylistId() === item._id"
                    [showActions]="!sidebarMode()"
                    [isDraggable]="isCustomSortActive()"
                    [isRefreshing]="isRefreshPending(item._id)"
                    [isDeleting]="isDeletePending(item._id)"
                    [busyMessage]="getBusyMessage(item)"
                    [busyProgress]="getBusyProgress(item._id)"
                    [canCancelBusyAction]="canCancelBusyOperation(item)"
                    (editPlaylistClicked)="openInfoDialog($event)"
                    (playlistClicked)="getPlaylist(item)"
                    (refreshClicked)="refreshPlaylist($event)"
                    (removeClicked)="removeClicked(item)"
                    (cancelBusyActionClicked)="cancelBusyOperation(item)"
                />
            }
        </div>
    }
}

