file.content:
.action-bar {
    position: sticky;
    bottom: calc(
        var(--settings-action-bar-offset) + var(--settings-safe-bottom)
    );
    margin-left: auto;
    z-index: 100;
    display: flex;
    justify-content: flex-end;
    align-items: center;
    gap: 12px;
    flex-wrap: wrap;
    padding: 10px 14px;
    border: 1px solid var(--settings-action-bar-border);
    border-radius: 18px;
    background: var(--settings-action-bar-bg);
    backdrop-filter: blur(12px);
    box-shadow: var(--settings-action-bar-shadow);
}

.settings-container.dialog-mode .action-bar {
    position: static;
    margin-top: 12px;
    margin-bottom: 2px;
    box-shadow: none;
    border-radius: 16px;
    padding: 12px;
    justify-content: space-between;
}

