.settings-save-button.mat-mdc-button-base {
    background: linear-gradient(135deg, #3b82f6 0%, #2563eb 100%);
    color: #fff;
    font-weight: 500;
    padding: 0 20px;
    border-radius: 10px;
    box-shadow: 0 4px 14px rgba(59, 130, 246, 0.28);
    transition:
        transform 0.2s ease,
        box-shadow 0.2s ease,
        opacity 0.2s ease;

    mat-icon {
        margin-right: 6px;
    }

    &:hover:not([disabled]) {
        transform: translateY(-1px);
        box-shadow: 0 6px 18px rgba(59, 130, 246, 0.38);
    }

    &:active:not([disabled]) {
        transform: translateY(0);
    }

    &[disabled] {
        background: color-mix(
            in srgb,
            var(--mat-sys-on-surface) 12%,
            transparent
        );
        color: color-mix(
            in srgb,
            var(--mat-sys-on-surface) 38%,
            transparent
        );
        box-shadow: none;
    }
}

