.workspace-shell {
    display: grid;
    grid-template-columns: 60px 1fr;
    grid-template-rows: 56px minmax(0, 1fr) auto;
    width: 100%;
    height: 100%;
    min-height: 0;
    overflow: hidden;
    background: var(--app-shell-bg, var(--mat-sys-surface));
    color: var(--mat-sys-on-surface);
}

app-workspace-shell-rail {
    grid-column: 1;
    grid-row: 1 / span 3;
    min-height: 0;
}

app-workspace-shell-header {
    grid-column: 2;
    grid-row: 1;
    min-width: 0;
}

.workspace-body {
    grid-column: 2;
    grid-row: 2;
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    min-height: 0;
    min-width: 0;
    overflow: hidden;
    background: var(--app-rail-bg, var(--mat-sys-surface-container-low));

    &.single-pane {
        grid-template-columns: 1fr;
    }
}

app-workspace-shell-context-sidebar {
    min-width: 0;
    min-height: 0;
}

.workspace-now-playing {
    grid-column: 2;
    grid-row: 3;
    padding: 0 12px 12px;
    background: var(--app-content-bg, var(--mat-sys-surface));
}

.workspace-content {
    min-width: 0;
    min-height: 0;
    overflow: auto;
    background: var(--app-content-bg, var(--mat-sys-surface));
    border-radius: 16px 0 0 0;
    box-shadow: -4px 8px 20px var(--app-content-shadow, rgba(0, 0, 0, 0.18));
}

.workspace-loading-overlay {
    position: fixed;
    inset: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 24px;
    background:
        radial-gradient(
            circle at top,
            rgba(99, 120, 255, 0.12),
            transparent 34%
        ),
        rgba(8, 10, 16, 0.68);
    backdrop-filter: blur(14px);
    z-index: 1000;
}

.workspace-loading-overlay__card {
    width: min(440px, 100%);
    display: grid;
    gap: 14px;
    padding: 24px 24px 20px;
    border-radius: 24px;
    border: 1px solid var(--app-separator, rgba(255, 255, 255, 0.12));
    background:
        linear-gradient(
            180deg,
            rgba(255, 255, 255, 0.06),
            rgba(255, 255, 255, 0)
        ),
        var(--mat-sys-surface-container-high);
    box-shadow:
        0 24px 64px rgba(0, 0, 0, 0.32),
        0 1px 0 rgba(255, 255, 255, 0.05) inset;
    text-align: center;
    animation: workspace-loading-overlay-enter 180ms ease-out;

    h3 {
        margin: 0;
        font-size: 1.55rem;
        font-weight: 650;
        letter-spacing: -0.03em;
        color: var(--app-heading-color, var(--mat-sys-on-surface));
    }
}

.workspace-loading-overlay__header {
    display: grid;
    gap: 10px;
    justify-items: center;
}

.workspace-loading-overlay__badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    padding: 6px 12px;
    border-radius: 999px;
    border: 1px solid rgba(120, 220, 255, 0.24);
    background: rgba(120, 220, 255, 0.08);
    color: rgba(164, 233, 255, 1);
    font-size: 0.72rem;
    font-weight: 700;
    letter-spacing: 0.12em;
    text-transform: uppercase;
}

.workspace-loading-overlay__badge--remote {
    border-color: rgba(105, 195, 255, 0.34);
    background: rgba(83, 158, 255, 0.12);
    color: rgba(202, 230, 255, 1);
}

.workspace-loading-overlay__phase,
.workspace-loading-overlay__detail,
.workspace-loading-overlay__progress-copy {
    margin: 0;
}

.workspace-loading-overlay__phase {
    font-size: 1rem;
    font-weight: 560;
    color: var(--app-body-color, var(--mat-sys-on-surface));
}

.workspace-loading-overlay__detail {
    max-width: 32ch;
    justify-self: center;
    color: var(--app-muted-color, var(--mat-sys-on-surface-variant));
    line-height: 1.45;
}

.workspace-loading-overlay__progress-copy {
    max-width: 30ch;
    justify-self: center;
    line-height: 1.45;
    font-variant-numeric: tabular-nums;
    color: var(--app-muted-color, var(--mat-sys-on-surface-variant));
    text-wrap: balance;
}

.workspace-loading-overlay__action {
    justify-self: center;
    min-width: 180px;
    border-radius: 999px;
}

:host ::ng-deep .workspace-loading-overlay__card .mat-mdc-progress-bar {
    overflow: hidden;
    border-radius: 999px;
}

@keyframes workspace-loading-overlay-enter {
    from {
        opacity: 0;
        transform: translateY(10px) scale(0.985);
    }

    to {
        opacity: 1;
        transform: translateY(0) scale(1);
    }
}

@media (max-width: 780px) {
    .workspace-shell {
        grid-template-columns: 56px 1fr;
        grid-template-rows: 56px 1fr auto;
    }
}

@media (max-width: 640px) {
    .workspace-shell {
        grid-template-columns: 1fr;
        grid-template-rows: 52px 56px minmax(0, 1fr) auto;
    }

    app-workspace-shell-rail {
        grid-column: 1;
        grid-row: 1;
    }

    app-workspace-shell-header {
        grid-column: 1;
        grid-row: 2;
    }

    .workspace-body {
        grid-column: 1;
        grid-row: 3;
    }

    .workspace-now-playing {
        grid-column: 1;
        grid-row: 4;
    }
}

