const fs = require('fs');
const path = require('path');
const I18N_DIR = '/Users/4gray/Code/iptvnator/apps/web/src/assets/i18n';
const additions = {
    WORKSPACE: { SHELL: { EXTERNAL_PLAYBACK_CLOSE: 'Close player' } },
};
function mergeMissing(target, source) {
    let added = 0;
    for (const key of Object.keys(source)) {
        const value = source[key];
        if (value && typeof value === 'object' && !Array.isArray(value)) {
            if (!target[key] || typeof target[key] !== 'object') target[key] = {};
            added += mergeMissing(target[key], value);
        } else if (!(key in target)) {
            target[key] = value;
            added += 1;
        }
    }
    return added;
}
const locales = fs.readdirSync(I18N_DIR).filter((f) => f.endsWith('.json') && f !== 'en.json');
for (const locale of locales) {
    const filePath = path.join(I18N_DIR, locale);
    const content = JSON.parse(fs.readFileSync(filePath, 'utf-8'));
    const added = mergeMissing(content, additions);
    if (added > 0) fs.writeFileSync(filePath, JSON.stringify(content, null, 4) + '\n', 'utf-8');
    console.log(`${locale}: +${added}`);
}
