import { PlayerContentInfo } from './portal-playback.interface';

export type ExternalPlayerName = 'mpv' | 'vlc';

export type ExternalPlayerSessionStatus =
    | 'launching'
    | 'opened'
    | 'playing'
    | 'error'
    | 'closed';

