    display: grid;
    place-items: center;
    color: var(--mat-sys-on-surface-variant);
}

.external-playback-dock__meta {
    min-width: 0;
}

.external-playback-dock__topline {
    display: flex;
    align-items: center;
    gap: 8px;
    margin-bottom: 3px;
}

.external-playback-dock__chip {
    display: inline-flex;
    align-items: center;
    height: 20px;
    padding: 0 8px;
