    font-size: 0.68rem;
    font-weight: 700;
    letter-spacing: 0.08em;
}

.external-playback-dock__caption {
    color: var(--mat-sys-on-surface-variant);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
}

.external-playback-dock__title {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
    font-size: 0.95rem;
    font-weight: 700;
    color: var(--mat-sys-on-surface);
}

.external-playback-dock__status {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-top: 4px;
    color: var(--mat-sys-on-surface-variant);
    font-size: 0.78rem;

    mat-icon {
        width: 16px;
        height: 16px;
        font-size: 16px;
    }

    mat-spinner {
        flex-shrink: 0;
    }
}

.external-playback-dock__actions {
    display: flex;
    align-items: center;
    gap: 6px;
}

.external-playback-dock__button {
    border-radius: 999px;
    white-space: nowrap;
}

@media (max-width: 720px) {
    .external-playback-dock {
        grid-template-columns: auto minmax(0, 1fr) auto;
    }

    .external-playback-dock:not(.external-playback-dock--compact) {
        .external-playback-dock__button span {
            display: none;
        }
    }
}

